<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/** Append-only wallet ledger row. Only `status` may change after insert (enforced by trigger). */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $wallet_id
 * @property string $user_id
 * @property string $type
 * @property string $direction
 * @property string $bucket
 * @property int $amount
 * @property string $currency
 * @property string $status
 * @property string $description
 * @property string|null $detail
 * @property string|null $order_id
 * @property string|null $payout_id
 * @property string|null $idempotency_key
 * @property Carbon $occurred_at
 * @property Carbon $created_at
 */
/* @properties-end */
class LedgerEntry extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'tx';

    public $timestamps = false;

    protected $fillable = [
        'wallet_id', 'user_id', 'type', 'direction', 'bucket', 'amount', 'currency', 'status', 'description',
        'detail', 'order_id', 'payout_id', 'idempotency_key', 'occurred_at', 'created_at',
    ];

    protected function casts(): array
    {
        return [
            'occurred_at' => 'datetime',
            'created_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<Wallet, $this> */
    public function wallet(): BelongsTo
    {
        return $this->belongsTo(Wallet::class);
    }

    /** @return BelongsTo<Order, $this> */
    public function order(): BelongsTo
    {
        return $this->belongsTo(Order::class);
    }
}
